input.command:
$paths = @(
  "$env:LOCALAPPDATA\Atlassian\SourceTree",
  "$env:APPDATA\Atlassian\SourceTree",
  "$env:USERPROFILE\.sourcetree",
  "$env:LOCALAPPDATA\Sourcetree"
); foreach ($p in $paths) { if (Test-Path $p) { Write-Host "EXISTS: $p"; Get-ChildItem $p -Force | Select-Object Name, Length, LastWriteTime } else { Write-Host "MISSING: $p" } }
